package com.stayease.service; import com.stayease.dto.AuthDtos.*;import com.stayease.entity.User;import com.stayease.exception.ApiException;import com.stayease.repository.UserRepository;import com.stayease.security.JwtService;import org.springframework.http.HttpStatus;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import java.time.LocalDateTime;
@Service public class AuthService {private final UserRepository users;private final PasswordEncoder encoder;private final JwtService jwt;public AuthService(UserRepository u,PasswordEncoder e,JwtService j){users=u;encoder=e;jwt=j;} public void register(RegisterRequest r){System.out.println("[AuthService.register] email="+r.email());if(users.existsByEmailIgnoreCase(r.email()))throw new ApiException(HttpStatus.CONFLICT,"EMAIL_EXISTS","Email already registered");User u=new User();u.setEmail(r.email().trim().toLowerCase());u.setName(r.name().trim());u.setPasswordHash(encoder.encode(r.password()));u.setRole("GUEST");u.setCreatedAt(LocalDateTime.now());users.save(u);} public LoginResponse login(LoginRequest r){System.out.println("[AuthService.login] email="+r.email());User u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Invalid email or password"));if(!encoder.matches(r.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"INVALID_CREDENTIALS","Invalid email or password");return new LoginResponse(jwt.generate(u));} public void logout(){}}
